export const meta = {
  name: 'map-rank-one-integration-cone',
  description: 'Map the AJCR Pic0 rank-one integration cone: locus API, divisor side, producer API, roadmap, inbox context',
  phases: [{ title: 'Map' }],
}

const ROOT = '/home/axel/LeanAlgebraicGeometry-Horizon'
const AJCR = ROOT + '/MainProjects/Algebraic-Jacobian-Challenge-Rebuild'

const REPORT = {
  type: 'object',
  properties: {
    summary: { type: 'string', description: 'Detailed technical report in markdown' },
  },
  required: ['summary'],
}

const tasks = [
  {
    label: 'locus-api',
    prompt: `You are mapping Lean 4 code in ${AJCR}/AlgebraicJacobian/Picard/. Read Pic0RankOneLocus.lean, Pic0RankOneLocusNative.lean, and any file defining picRankOneOpenSigmaIncl and PicRankOneOpen.FibrePresented and picRankOneOpen_isOpen_of_fibrePresented (grep for them). Report precisely, with full Lean signatures: (1) the definition of PicRankOneOpen pi (what data its membership predicate carries, as subfunctor of what), (2) PicRankOneOpen.IsOpen pi — exact statement, (3) PicRankOneOpen.FibrePresented — fields, (4) picRankOneOpen_isOpen_of_fibrePresented — hypotheses, (5) picRankOneOpenSigmaIncl, (6) mem_picRankOneOpen_of_nativePresentations — exact hypotheses, (7) any existing lemmas about naturality/base-change of membership. Be exhaustive on signatures; this feeds a proof-planning step.`,
  },
  {
    label: 'divisor-side',
    prompt: `You are mapping Lean 4 code in ${AJCR}/AlgebraicJacobian/Picard/. Find (grep) and read the definitions of divRankOnePresentationPreimageRepresenter, rankOneAbelRepresented, DivRankOneOpen, DivRankOneOpenData, divRankOneOpenData_of_picRankOneOpen_isOpen, divRankOneOpen_isOpenImmersion, divRankOneOpen_mem_iff, divRankOneOpen_baseChange_mem (likely DivRankOneOpen.lean and neighbors). Report with full Lean signatures: (1) what functor divRankOnePresentationPreimageRepresenter represents and over what carrier scheme, (2) exact statement of rankOneAbelRepresented (the restricted Abel natural transformation), (3) how DivRankOneOpen is conditional on DivRankOneOpenData / PicRankOneOpen.IsOpen, (4) what remains missing to produce an unconditional DivRankOneOpen. Be exhaustive on signatures.`,
  },
  {
    label: 'producer-api',
    prompt: `You are mapping Lean 4 code in ${AJCR}/AlgebraicJacobian/Picard/ and ${AJCR}/AlgebraicJacobian/Cohomology/. Read Pic0RankOneNativePresentation.lean, Pic0RankOneNativePresentationOfLocal.lean, Pic0RankOneNativePresentationSplit.lean, Pic0RankOneNativePresentationDatum.lean, Pic0RankOneFibrePresentedProducerFiniteGlue.lean, and skim Pic0RankOneLocalDivisor.lean. Report with full Lean signatures: (1) PicRankOneNativePresentation pi lam — fields and constructors (ofCertificates, ofLocalPresentation, ofNativeDatum, ofCertificatesWithNativeBaseChange), (2) PicRankOneLocalPresentation — key fields, (3) exists_glued_rankOne_away_divisor_with_abel_evaluation — EXACT statement including what carrier it produces the DivFamZarAff over and what identities it carries, (4) baseOpenRankOneDivisor and its picClass/abelAff lemmas, (5) what a 'descent of the glued family divisor from the etale carrier to the arbitrary affine base' would need. Be exhaustive on signatures.`,
  },
  {
    label: 'board-state',
    prompt: `Run these commands and synthesize: HORIZON_BIN=$(printenv HORIZON_BIN); "$HORIZON_BIN" roadmap list --focus AJCR.review-plan (and read every item's strategy notes via "$HORIZON_BIN" roadmap show <id> for each child); also "$HORIZON_BIN" roadmap list --focus AJCR.w4-rep --max-depth 2 if it exists. Then "$HORIZON_BIN" graph -p Algebraic-Jacobian-Challenge-Rebuild frontier | head -40. Report: (1) each AJCR.review-plan child with status/owner/strategy verbatim-condensed, (2) which phase items are done/blocked/active and what their notes say the next concrete step is, (3) top graph frontier nodes relevant to rank-one/representability. NOTE: if a command errors, record the error and move on.`,
  },
  {
    label: 'inbox-context',
    prompt: `Run: HORIZON_BIN=$(printenv HORIZON_BIN); "$HORIZON_BIN" inbox list --mine --unread --json (all unread), and "$HORIZON_BIN" inbox show I-1927 --json, I-1979, and any items whose title mentions rank-one, producer, integration, family, or Abel. Also "$HORIZON_BIN" inbox list --kind memory --json | grep-filter for rank-one/abel/producer relevant memory items and show the relevant ones. Report: (1) every unread item id + one-line gist + whether it is relevant to the Pic0 rank-one integration cone task, (2) full content-condensed of the relevant ones (I-1927 thread especially — the parallel-lane coordination thread), (3) any standing dead-ends/warnings (stale olean hazard I-1979) that affect building. Do NOT archive or modify anything.`,
  },
]

phase('Map')
const results = await parallel(tasks.map(t => () =>
  agent(t.prompt, { label: t.label, phase: 'Map', schema: REPORT, model: 'opus', effort: 'high' })
))
return Object.fromEntries(results.map((r, i) => [tasks[i].label, r ? r.summary : 'AGENT FAILED']))

